-- 0008_add_intake_handover_card — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- Intake (SOP-DEL-01, E2): the Handover Card Sales fills per project (Annex B) and the package checklist
-- items it covers (§6, A1…G1). Internal only: clients and partners never see a Handover Card. Restricted
-- content (group F) never lives here — only that it was recorded in the restricted Internal Notes (AC7).
CREATE TABLE handover_card (
  id           uuid PRIMARY KEY,
  client_id    uuid NOT NULL,
  -- The project the card hands over (Annex B §1 Project ID); its client must be the card's client.
  site_id      uuid NOT NULL,
  -- A returned card is resubmitted as the next version; earlier versions stay (Intake Register, AC6).
  version      integer NOT NULL CHECK (version >= 1),
  package      text NOT NULL CHECK (package IN ('full', 'light')),
  status       text NOT NULL DEFAULT 'draft' CHECK (status IN
                 ('draft', 'submitted', 'accepted', 'accepted_with_conditions', 'returned')),
  -- Annex B sections 1–11, validated by the zod schema in @ocs/contracts before every write.
  content      jsonb NOT NULL DEFAULT '{}',
  submitted_at timestamptz,
  submitted_by uuid,
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz,
  UNIQUE (id, client_id),
  UNIQUE (site_id, version),
  CHECK ((status = 'draft') = (submitted_at IS NULL)),
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX handover_card_client ON handover_card (client_id);
-- One card in play per project: at most one draft or submitted card at a time.
CREATE UNIQUE INDEX handover_card_open ON handover_card (site_id)
  WHERE status IN ('draft', 'submitted') AND archived_at IS NULL;

-- One row per §6 checklist item the package covers. An item not yet covered has no row; the package is
-- complete when every item required for its package (Full / Light) has one (rule in core/intake).
CREATE TABLE handover_item (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL,
  card_id     uuid NOT NULL,
  code        text NOT NULL CHECK (code ~ '^[A-G][1-9]$'),
  status      text NOT NULL CHECK (status IN ('provided', 'na')),
  -- English summary or a pointer into the project folder (SOP-DEL-02).
  value       text,
  file_ref    text,
  -- SOP-DEL-01 §6 / Annex B: "Not applicable → write N/A and the reason" (E2 AC1).
  na_reason   text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  UNIQUE (card_id, code),
  CHECK ((status = 'na') = (na_reason IS NOT NULL AND btrim(na_reason) <> '')),
  -- E2 AC7: what was promised verbally, conceded or said about people stays in the restricted Internal Notes.
  CHECK (code NOT LIKE 'F%' OR value IS NULL),
  FOREIGN KEY (card_id, client_id) REFERENCES handover_card (id, client_id)
);
CREATE INDEX handover_item_client ON handover_item (client_id);

ALTER TABLE handover_card ENABLE ROW LEVEL SECURITY;
CREATE POLICY handover_card_internal ON handover_card FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
ALTER TABLE handover_item ENABLE ROW LEVEL SECURITY;
CREATE POLICY handover_item_internal ON handover_item FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
-- No client or partner policy: internal Sales → Delivery documents. No DELETE: archive with archived_at.
GRANT SELECT, INSERT, UPDATE ON handover_card, handover_item TO ocs_app;
